            let mut taken: Option<Box<Node>> = None;
            n.children.set_and_swap(idx, &mut taken);
            let r: Option<Box<Node>> = match taken {
                None => None,
                Some(ch) => delete_node(ch, key.subrange(1, key.len() as int)),
            };
            let rnone = r.is_none();
            n.children.set(idx, r);
            proof {
                lemma_step(oe, oc, n.is_end, n.children@, idx as int, n.children@[idx as int], key);
                lemma_view_eq(&*n, ov, oe, oc, key);
