    proof fn lemma_snap(n: &Node)
        ensures
            forall |k: Seq<u8>| #[trigger] n.view().contains(k) == pv(n.is_end, n.children@, k),
    {
        assert forall |k: Seq<u8>| #[trigger] n.view().contains(k) == pv(n.is_end, n.children@, k) by {
            if k.len() > 0 {
                let c = k[0] as int;
                if 0 <= c < n.children.len() {
                    match &n.children[c] {
                        Some(child) => { assert(child.view().contains(k.subrange(1, k.len() as int))); }
                        None => {}
                    }
                }
            }
        }
    }

    proof fn lemma_empty(n: &Node)
        requires
            n.children.len() == 256,
            no_kids(n),
            !n.is_end,
        ensures
            forall |k: Seq<u8>| !(#[trigger] n.view().contains(k)),
    {
        lemma_snap(n);
        assert forall |k: Seq<u8>| !(#[trigger] n.view().contains(k)) by {
            if k.len() > 0 {
                let c = k[0] as int;
                assert(n.children[c].is_none());
            }
        }
    }

    proof fn lemma_step(oe: bool, oc: Seq<Option<Box<Node>>>, ne: bool, nc: Seq<Option<Box<Node>>>,
                        idx: int, r: Option<Box<Node>>, key: Seq<u8>)
        requires
            oc.len() == 256,
            nc == oc.update(idx, r),
            ne == oe,
            key.len() > 0,
            key[0] as int == idx,
            0 <= idx < 256,
            opt_view(r) =~= opt_view(oc[idx]).remove(key.subrange(1, key.len() as int)),
        ensures
            forall |k: Seq<u8>| pv(ne, nc, k) == (pv(oe, oc, k) && k != key),
    {
        let kt = key.subrange(1, key.len() as int);
        assert forall |k: Seq<u8>| pv(ne, nc, k) == (pv(oe, oc, k) && k != key) by {
            if k.len() == 0 {
                assert(k != key);
            } else {
                let c = k[0] as int;
                let t = k.subrange(1, k.len() as int);
                if c == idx {
                    assert(opt_view(r).contains(t) == (opt_view(oc[idx]).contains(t) && t != kt));
                    assert(k != key <==> t != kt) by {
                        if t =~= kt {
                            assert(k =~= key);
                        }
                        if k =~= key {
                            assert(t =~= kt);
                        }
                    }
                } else {
                    assert(nc[c] == oc[c]);
                    assert(k != key) by {
                        if k =~= key { assert(k[0] == key[0]); }
                    }
                }
            }
        }
    }

    proof fn lemma_end(oe: bool, oc: Seq<Option<Box<Node>>>, ne: bool, nc: Seq<Option<Box<Node>>>, key: Seq<u8>)
        requires
            key.len() == 0,
            ne == false,
            nc == oc,
        ensures
            forall |k: Seq<u8>| pv(ne, nc, k) == (pv(oe, oc, k) && k != key),
    {
        assert forall |k: Seq<u8>| pv(ne, nc, k) == (pv(oe, oc, k) && k != key) by {
            if k.len() == 0 {
                assert(k =~= key);
            }
        }
    }

    proof fn lemma_view_eq(n: &Node, ov: Set<Seq<u8>>, oe: bool, oc: Seq<Option<Box<Node>>>, key: Seq<u8>)
        requires
            forall |k: Seq<u8>| ov.contains(k) == pv(oe, oc, k),
            forall |k: Seq<u8>| pv(n.is_end, n.children@, k) == (pv(oe, oc, k) && k != key),
        ensures
            n.view() =~= ov.remove(key),
    {
        lemma_snap(n);
        assert forall |k: Seq<u8>| n.view().contains(k) == ov.remove(key).contains(k) by {
            assert(ov.remove(key).contains(k) == (ov.contains(k) && k != key));
        }
    }
