    spec fn no_kids(n: &Node) -> bool {
        forall |i: int| 0 <= i < 256 ==> #[trigger] n.children[i].is_none()
    }

    // Membership expressed from is_end and a children sequence.
    spec fn pv(e: bool, cs: Seq<Option<Box<Node>>>, k: Seq<u8>) -> bool {
        if k.len() == 0 {
            e
        } else {
            let c = k[0] as int;
            0 <= c < cs.len() && opt_view(cs[c]).contains(k.subrange(1, k.len() as int))
        }
    }

    fn has_no_kids(n: &Node) -> (b: bool)
        requires
            n.children.len() == 256,
        ensures
            b == no_kids(n),
    {
        let mut i: usize = 0;
        let mut ok: bool = true;
        while i < 256
            invariant
                0 <= i <= 256,
                n.children.len() == 256,
                ok == (forall |j: int| 0 <= j < i ==> #[trigger] n.children[j].is_none()),
            decreases 256 - i,
        {
            if n.children[i].is_some() {
                ok = false;
            }
            i = i + 1;
        }
        ok
    }

    // Deletes the suffix key[pos..] from node.
    fn delete_node(node: Box<Node>, key: Seq<u8>, pos: usize) -> (res: Option<Box<Node>>)
        requires
            node.well_formed(),
            pos <= key.len(),
        ensures
            opt_well_formed(res),
            opt_view(res) =~= node.view().remove(key.subrange(pos as int, key.len() as int)),
        decreases key.len() - pos,
    {
        let ghost oe = node.is_end;
        let ghost oc = node.children@;
        let ghost ov = node.view();
        let ghost sk = key.subrange(pos as int, key.len() as int);
        let mut n = node;
        proof {
            lemma_snap(&*n);
            assert forall |k: Seq<u8>| ov.contains(k) == pv(oe, oc, k) by {
                assert(ov.contains(k) == pv(n.is_end, n.children@, k));
            }
        }
        if pos == key.len() {
            n.is_end = false;
            proof {
                assert(sk =~= Seq::<u8>::empty());
                lemma_end(oe, oc, n.is_end, n.children@, sk);
                lemma_view_eq(&*n, ov, oe, oc, sk);
            }
            if has_no_kids(&n) {
                proof { lemma_empty(&*n); }
                None
            } else {
                Some(n)
            }
        } else {
            let idx: usize = key[pos as int] as usize;
            let mut taken: Option<Box<Node>> = None;
            n.children.set_and_swap(idx, &mut taken);
            let r: Option<Box<Node>> = match taken {
                None => None,
                Some(ch) => delete_node(ch, key, pos + 1),
            };
            let rnone = r.is_none();
            n.children.set(idx, r);
            proof {
                lemma_step(oe, oc, n.is_end, n.children@, idx as int, n.children@[idx as int], sk);
                lemma_view_eq(&*n, ov, oe, oc, sk);
            }
            if rnone && has_no_kids(&n) && !n.is_end {
                proof { lemma_empty(&*n); }
                None
            } else {
                Some(n)
            }
        }
    }
